51	    /// <inheritdoc />
52	    public virtual IVectorStoreRecordCollection<TKey, TRecord> GetCollection<TKey, TRecord>(string name, VectorStoreRecordDefinition? vectorStoreRecordDefinition = null)
53	        where TKey : notnull
54	    {
55	#pragma warning disable CS0618 // ISqliteVectorStoreRecordCollectionFactory is obsolete
56	        if (this._options.VectorStoreCollectionFactory is not null)
57	        {
58	            return this._options.VectorStoreCollectionFactory.CreateVectorStoreRecordCollection<TKey, TRecord>(
59	                this._connectionString,
60	                name,
61	                vectorStoreRecordDefinition);
62	        }
63	#pragma warning restore CS0618
64	
65	        if (typeof(TKey) != typeof(string) && typeof(TKey) != typeof(ulong))
66	        {
67	            throw new NotSupportedException($"Only {nameof(String)} and {nameof(UInt64)} keys are supported.");
68	        }
